create or replace function public.current_user_business_role(p_business_id uuid) returns text language sql security definer set search_path=public,pg_temp as $$ select coalesce((select lower(bm.role::text) from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() limit 1),case when exists(select 1 from profiles p where p.id=auth.uid() and p.is_admin=true) then 'admin' else null end); $$;
create or replace function public.can_manage_business(p_business_id uuid) returns boolean language sql security definer set search_path=public,pg_temp as $$ select coalesce(public.current_user_business_role(p_business_id) in ('owner','admin'),false); $$;
revoke all on function public.current_user_business_role(uuid) from public; grant execute on function public.current_user_business_role(uuid) to authenticated;
revoke all on function public.can_manage_business(uuid) from public; grant execute on function public.can_manage_business(uuid) to authenticated;
create or replace function public.business_management_context(p_business_id uuid) returns jsonb language sql security definer set search_path=public,pg_temp as $$ select jsonb_build_object('business_id',p_business_id,'role',public.current_user_business_role(p_business_id),'can_manage',public.can_manage_business(p_business_id),'can_manage_campaigns',public.can_manage_business(p_business_id),'can_manage_promotions',public.can_manage_business(p_business_id),'can_manage_qr',public.can_manage_business(p_business_id),'can_manage_media',public.can_manage_business(p_business_id),'can_manage_partnerships',public.can_manage_business(p_business_id),'can_manage_events',public.can_manage_business(p_business_id)); $$;
revoke all on function public.business_management_context(uuid) from public; grant execute on function public.business_management_context(uuid) to authenticated;
